"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["4465"],{62860(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>c,contentTitle:()=>d,toc:()=>p,assets:()=>l});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-get-session","title":"Get session token","description":"Exchanges the participant\'s client_id and client_secret (OAuth 2.0 client credentials) for a Bearer access_token valid for 1200 seconds.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-get-session.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-get-session","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/endpoints/registry-get-session","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get session token","sidebar_label":"Get session token","sidebar_class_name":"api-method api-method--post","description":"Exchanges the participant\'s client_id and client_secret (OAuth 2.0 client credentials) for a Bearer access_token valid for 1200 seconds.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/"},"next":{"title":"Participant update (v1)","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/endpoints/registry-participant-update"}}'),a=n(62540),s=n(43023),r=n(44136),o=JSON.parse('{"id":"registry_get_session","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/get/session","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get session token","description":"Exchanges the participant\'s client_id and client_secret (OAuth 2.0 client credentials) for a Bearer access_token valid for 1200 seconds.\\n\\n### Business purpose\\n\\nEvery NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing. It answers the question of who is calling the gateway. It is deliberately separate from payload confidentiality: a request can be perfectly encrypted and still fail with 401, and vice versa.\\n\\n### When to use\\n\\nCall it at start-up and whenever the cached token is close to expiry. The Integration Handbook documents it as POST /get/session on host apisbx.abdm.gov.in with Content-Type application/x-www-form-urlencoded and body client_id=<NHCX_CLIENT_ID>&client_secret=<NHCX_CLIENT_SECRET>&grant_type=client_credentials. The response carries access_token, expires_in 1200 and token_type Bearer. Both sandbox-exit checklists list /get/session as the auth-token API. Note that the FAQ instead lists https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions as the Session API, and the OpenAPI entry (operationId getSession) calls the operation internal and returns ParticipantSessionResponse with a single accessToken field; confirm the current host with your onboarding contact. There is no refresh token: renewal is simply another client-credentials call.\\n\\n### Preconditions\\n\\n- client_id and client_secret issued at the end of onboarding; client_secret is generated by the NHCX instance, stored encrypted and never returned by any registry API, so a lost secret must be reissued.\\n- Credentials scoped to the right environment; sandbox credentials do not work against production and vice versa.\\n- Content-Type application/x-www-form-urlencoded with grant_type=client_credentials fixed; the two secrets are the only variables.\\n- No Bearer token is needed for this call itself.\\n\\n### Postconditions\\n\\nHTTP 200 with { access_token, expires_in: 1200, token_type: Bearer }. The access_token is a JWT that should be treated as opaque; place it in the Authorization (bearer_auth) header as Bearer <token> on every subsequent call. Its lifetime is 1200 seconds (20 minutes); after that any call returns 401. The OpenAPI schema names the field accessToken and omits expiry, so read whichever key is present and assume 1200 seconds when expires_in is absent. A 400 indicates a malformed body. Nothing asynchronous follows.\\n\\n### Common mistakes\\n\\n- Not implementing automatic refresh, so calls that worked minutes ago start returning 401 or 401 Unauthorized - Sender is not authorized to execute the operation once 20 minutes pass.\\n- Sending the token without the Bearer prefix in bearer_auth, which also produces a plain 401.\\n- Using the wrong Content-Type (JSON instead of form-urlencoded), omitting grant_type=client_credentials, or misspelling a credential field, which yields 400.\\n- Minting a fresh token for every transaction instead of caching it.\\n- Continuing to use a cached client_secret after the instance rotated it; every token minted from the old secret stops working.\\n- Pairing a sandbox token with the production gateway.\\n\\n### Best practices\\n\\n- Cache the token in memory keyed by environment and refresh proactively at roughly 80 to 90 percent of the lifetime computed from the expires_in actually received.\\n- Serialise refresh behind a lock so concurrent workers do not fire simultaneous token requests.\\n- On any 401, discard the cached token, mint a new one and replay the original request exactly once; if the second attempt also fails, stop and alert, since the credentials are wrong or revoked.\\n- Never log the access_token or client_secret; log the expiry timestamp instead.\\n- Store secrets so they can be rotated without a code deploy.\\n- The token is validated by ABDM, so a 401 on any NHCX call carries no hint that expiry is the cause; treat 401 as refresh-and-retry first.\\n\\n### Related scenario\\n\\nAt 09:00 a hospital\'s claims engine starts and POSTs its client_id and client_secret to /get/session, receiving an access_token with expires_in 1200. It caches the token and immediately calls /fetch/certs for the payer it will submit to. At 09:17 a background timer renews the token before the 20-minute mark, so the /v1/preauth/submit sent at 09:21 carries a fresh Bearer header. Later a worker receives a 401 after a network stall; it drops the cached token, calls /get/session once more, replays the request and succeeds. Had the second attempt also failed, the engine would have alerted operations rather than looping.\\n\\n### Specification\\n\\nChapter [Base URLs](/docs/nhcx/v1/getting-started/base-urls) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"_contentType","type":"string","required":false,"description":"","encrypted":false},{"name":"client_id","type":"string","required":false,"description":"","encrypted":false},{"name":"client_secret","type":"string","required":false,"description":"","encrypted":false},{"name":"grant_type","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"_contentType":"application/x-www-form-urlencoded","client_id":"<NHCX_CLIENT_ID>","client_secret":"<NHCX_CLIENT_SECRET>","grant_type":"client_credentials"},"responses":[{"status":"200","description":"HTTP 200 with { access_token, expires_in: 1200, token_type: Bearer }.","example":{"access_token":"eyJhbGciOiJSUzI1NiIs...","expires_in":1200,"token_type":"Bearer"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/get/session \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"_contentType\\": \\"application/x-www-form-urlencoded\\",\\n  \\"client_id\\": \\"<NHCX_CLIENT_ID>\\",\\n  \\"client_secret\\": \\"<NHCX_CLIENT_SECRET>\\",\\n  \\"grant_type\\": \\"client_credentials\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/get/session \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"_contentType\\": \\"application/x-www-form-urlencoded\\",\\n  \\"client_id\\": \\"<NHCX_CLIENT_ID>\\",\\n  \\"client_secret\\": \\"<NHCX_CLIENT_SECRET>\\",\\n  \\"grant_type\\": \\"client_credentials\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/get/session\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"_contentType\\": \\"application/x-www-form-urlencoded\\",\\n        \\"client_id\\": \\"<NHCX_CLIENT_ID>\\",\\n        \\"client_secret\\": \\"<NHCX_CLIENT_SECRET>\\",\\n        \\"grant_type\\": \\"client_credentials\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/get/session\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"_contentType\\": \\"application/x-www-form-urlencoded\\",\\n    \\"client_id\\": \\"<NHCX_CLIENT_ID>\\",\\n    \\"client_secret\\": \\"<NHCX_CLIENT_SECRET>\\",\\n    \\"grant_type\\": \\"client_credentials\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Get session token",sidebar_label:"Get session token",sidebar_class_name:"api-method api-method--post",description:"Exchanges the participant's client_id and client_secret (OAuth 2.0 client credentials) for a Bearer access_token valid for 1200 seconds.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},d,l={},p=[];function h(e){return(0,a.jsx)(r.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);